static int pixels(ui_component_t *c,const char *name,unsigned char **header,size_t *length){ui_content_slot_t *slot=ui_shell_get_content_slot(ui_host_get_shell(host),NULL);ui_rect_t rect;ui_pixel_buffer_t b={0};ui_element_presentation_t p={0};ui_status_t s;ULONGLONG start;char path[1024];FILE *f;b.size=sizeof(b);p.size=sizeof(p);ui_content_slot_get_rect(slot,&rect);if(presentation(c,"columns",&p)!=UI_STATUS_OK)return 0;for(int allocate=0;allocate<2;++allocate){start=GetTickCount64();do{s=ui_component_capture_rgba(c,rect.width,rect.height,dpi_now,&b);if(s!=UI_STATUS_PENDING)break;pump(1);}while(GetTickCount64()-start<5000);if(s!=UI_STATUS_OK){free(b.pixels);return 0;}if(!allocate){b.capacity=b.stride*b.height;b.pixels=malloc(b.capacity);if(!b.pixels)return 0;}}snprintf(path,sizeof(path),"%s/%s.rgba",directory,name);f=fopen(path,"wb");if(f){fwrite(b.pixels,1,b.stride*b.height,f);fclose(f);}printf("PIXELS name=%s device=%zu,%zu stride=%zu header-view-logical=%d,%d,%d,%d\n",name,(size_t)b.width,(size_t)b.height,b.stride,p.rect.x,p.rect.y,p.rect.width,p.rect.height);{int y=MulDiv(p.rect.y,dpi_now,96),h=MulDiv(p.rect.height,dpi_now,96);if(y<0||y+h>(int)b.height){free(b.pixels);return 0;}*length=(size_t)b.width*h*4;*header=malloc(*length);for(int i=0;i<h;++i)memcpy(*header+(size_t)i*b.width*4,b.pixels+(size_t)(y+i)*b.stride,(size_t)b.width*4);snprintf(path,sizeof(path),"%s/%s-header.rgba",directory,name);f=fopen(path,"wb");if(f){fwrite(*header,1,*length,f);fclose(f);}}free(b.pixels);return 1;}
